window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-870cadabadeee8f9"]={"versions": [{"id": "FIG-870cadabadeee8f9", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) zur Veranschaulichung des Übertragungsmodus (Transmission Mode, TM) im AUTOSAR Communication Modul (COM). Das Diagramm stellt den Use Case A1 („TM periodic without TMS switch“) dar und visualisiert das Verhalten periodischer I-PDU-Übertragungen über eine Zeitachse in Relation zu internen Signal-Schreiboperationen der oberen Schichten (RTE/SWC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (Abszisse)</strong>: Kontinuierlicher Zeitstrahl der I-PDU-Verarbeitung.\n</li><li><strong>Grüne vertikale Pfeile nach unten</strong>: Periodische Sendezeitpunkte bzw. Sendeaufrufe der I-PDU durch AUTOSAR COM an die unterlagerte Schicht (PDU Router).\n</li><li><strong>tc</strong>: Zykluszeit (Periodizität) zwischen zwei regulären Sendezeitpunkten.\n</li><li><strong>Orangene Blitze mit Beschriftung <code>v = x</code></strong>: Modulinterne Aktualisierungen eines Signals (<code>Com_SendSignal</code>) durch Software-Komponenten/RTE mit einem Wert <code>x</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die I-PDU wird strikt zyklisch im festen Zeitintervall t_c übertragen, dargestellt durch die äquidistanten grünen Pfeile.\n</li><li>Mehrere Signalaktualisierungen (<code>v = x</code>, symbolisiert durch Blitze) treten asynchron zu den Sendezeitpunkten auf (z. B. zwischen erstem und zweitem sowie vor dem dritten Sendeereignis).\n</li><li>Da der Übertragungsmodus rein periodisch konfiguriert ist und kein TMS-Wechsel (Transmission Mode Selector) stattfindet, triggern die Signalaktualisierungen keine vorzeitige oder zusätzliche PDU-Aussendung.\n</li><li>Die I-PDU-Aussendung verbleibt vollständig entkoppelt von den Schreibereignissen im definierten Zyklus t_c.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Vorgabe</strong>: Bei rein periodischem Übertragungsmodus (Transmission Mode PERIODIC) führt das Schreiben von Signalen (<code>Com_SendSignal</code>) nicht zu einem direkten Sendeanstoß der zugeordneten I-PDU, sofern kein Event-Anteil konfiguriert ist.\n</li><li><strong>Pufferverhalten</strong>: Signalwerte werden im COM-internen Puffer aktualisiert und erst mit dem nächsten regulären periodischen Ablaufschritt (t_c) im Rahmen der zyklischen COM-Hauptfunktion bzw. des konfigurierten Timers gesendet.\n</li><li><strong>Konfiguration</strong>: Relevant für die Konfigurationsparameter <code>ComTxModeMode = PERIODIC</code> und <code>ComTxModeTimePeriod = tc</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-50e7d20963c8ad84", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) zur Veranschaulichung des Übertragungsmodus (Transmission Mode, TM) im AUTOSAR Communication Modul (COM). Das Diagramm stellt den Use Case A1 („TM periodic without TMS switch“) dar und visualisiert das Verhalten periodischer I-PDU-Übertragungen über eine Zeitachse in Relation zu internen Signal-Schreiboperationen der oberen Schichten (RTE/SWC).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse (Abszisse)</strong>: Kontinuierlicher Zeitstrahl der I-PDU-Verarbeitung.\n</li><li><strong>Grüne vertikale Pfeile nach unten</strong>: Periodische Sendezeitpunkte bzw. Sendeaufrufe der I-PDU durch AUTOSAR COM an die unterlagerte Schicht (PDU Router).\n</li><li><strong>tc</strong>: Zykluszeit (Periodizität) zwischen zwei regulären Sendezeitpunkten.\n</li><li><strong>Orangene Blitze mit Beschriftung <code>v = x</code></strong>: Modulinterne Aktualisierungen eines Signals (<code>Com_SendSignal</code>) durch Software-Komponenten/RTE mit einem Wert <code>x</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die I-PDU wird strikt zyklisch im festen Zeitintervall t_c übertragen, dargestellt durch die äquidistanten grünen Pfeile.\n</li><li>Mehrere Signalaktualisierungen (<code>v = x</code>, symbolisiert durch Blitze) treten asynchron zu den Sendezeitpunkten auf (z. B. zwischen erstem und zweitem sowie vor dem dritten Sendeereignis).\n</li><li>Da der Übertragungsmodus rein periodisch konfiguriert ist und kein TMS-Wechsel (Transmission Mode Selector) stattfindet, triggern die Signalaktualisierungen keine vorzeitige oder zusätzliche PDU-Aussendung.\n</li><li>Die I-PDU-Aussendung verbleibt vollständig entkoppelt von den Schreibereignissen im definierten Zyklus t_c.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Vorgabe</strong>: Bei rein periodischem Übertragungsmodus (Transmission Mode PERIODIC) führt das Schreiben von Signalen (<code>Com_SendSignal</code>) nicht zu einem direkten Sendeanstoß der zugeordneten I-PDU, sofern kein Event-Anteil konfiguriert ist.\n</li><li><strong>Pufferverhalten</strong>: Signalwerte werden im COM-internen Puffer aktualisiert und erst mit dem nächsten regulären periodischen Ablaufschritt (t_c) im Rahmen der zyklischen COM-Hauptfunktion bzw. des konfigurierten Timers gesendet.\n</li><li><strong>Konfiguration</strong>: Relevant für die Konfigurationsparameter <code>ComTxModeMode = PERIODIC</code> und <code>ComTxModeTimePeriod = tc</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-870cadabadeee8f9", "to": "FIG-50e7d20963c8ad84", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
